import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, getJob, toJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const send = (res: ServerResponse, status: number, body: unknown): void => {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
};
const errorBody = (code: string, message: string, fields?: { field: string; message: string }[]) => ({
  error: { code, message, ...(fields ? { fields } : {}) },
});

async function readBody(req: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const part of req) {
    const chunk = Buffer.isBuffer(part) ? part : Buffer.from(part);
    size += chunk.length;
    if (size > 1024 * 1024) throw new Error('body too large');
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown;
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  try {
    if (pathname === '/health') {
      if (req.method !== 'GET') return send(res, 405, errorBody('method_not_allowed', 'Method not allowed.'));
      const beat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
      return send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.seen_at <= 3000 ? 'up' : 'down' });
    }
    if (pathname === '/') {
      if (req.method !== 'GET') return send(res, 405, errorBody('method_not_allowed', 'Method not allowed.'));
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
      return;
    }
    if (pathname === '/api/jobs') {
      if (req.method === 'GET') {
        const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all();
        return send(res, 200, { jobs: rows.map(row => toJob(row as Parameters<typeof toJob>[0])) });
      }
      if (req.method !== 'POST') return send(res, 405, errorBody('method_not_allowed', 'Method not allowed.'));
      const fields: { field: string; message: string }[] = [];
      const contentType = req.headers['content-type'] ?? '';
      if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) {
        // Drain the request so the connection can be reused.
        req.resume();
        return send(res, 400, errorBody('invalid_request', 'Invalid request.', [{ field: 'body', message: 'Content-Type must be application/json.' }]));
      }
      let body: unknown;
      try { body = await readBody(req); }
      catch { return send(res, 400, errorBody('invalid_request', 'Invalid request.', [{ field: 'body', message: 'Request body must be valid JSON.' }])); }
      const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
      if (!isObject) {
        fields.push({ field: 'body', message: 'Body must be a JSON object.' });
      }
      const obj = isObject ? body as Record<string, unknown> : {};
      let steps: unknown = 5;
      let failAttempts: unknown = 0;
      if (isObject) {
        for (const key of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
        if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'This field is required.' });
        else if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
        else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({ field: 'input', message: 'Must contain 1–1000 characters and not be only whitespace.' });
        steps = Object.hasOwn(obj, 'steps') ? obj.steps : 5;
        failAttempts = Object.hasOwn(obj, 'failAttempts') ? obj.failAttempts : 0;
        if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
        if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
      }
      const rawIdem = req.headers['idempotency-key'];
      const idem = Array.isArray(rawIdem) ? undefined : rawIdem;
      if (Array.isArray(rawIdem) || (idem !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(idem))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, digits, underscores, or hyphens.' });
      if (fields.length) return send(res, 400, errorBody('invalid_request', 'Invalid request.', fields));

      const input = obj.input as string;
      const normalizedSteps = steps as number;
      const normalizedFails = failAttempts as number;
      const payload = JSON.stringify({ input, steps: normalizedSteps, failAttempts: normalizedFails });
      db.exec('BEGIN IMMEDIATE');
      try {
        if (idem !== undefined) {
          const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(idem) as { payload: string; job_id: string } | undefined;
          if (existing) {
            db.exec('COMMIT');
            if (existing.payload !== payload) return send(res, 409, errorBody('idempotency_conflict', 'This Idempotency-Key was already used with a different payload.'));
            return send(res, 200, getJob(db, existing.job_id));
          }
        }
        const id = randomUUID();
        const now = new Date().toISOString();
        db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,result,error,created_at,updated_at,available_at)
          VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0)`).run(id, input, normalizedSteps, normalizedFails, now, now);
        if (idem !== undefined) db.prepare('INSERT INTO idempotency (key,payload,job_id) VALUES (?,?,?)').run(idem, payload, id);
        db.exec('COMMIT');
        return send(res, 201, getJob(db, id));
      } catch (e) { db.exec('ROLLBACK'); throw e; }
    }
    const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
    if (match) {
      if (req.method !== 'GET') return send(res, 405, errorBody('method_not_allowed', 'Method not allowed.'));
      let id: string;
      try { id = decodeURIComponent(match[1]!); } catch { return send(res, 404, errorBody('not_found', 'Job not found.')); }
      const job = getJob(db, id);
      return job ? send(res, 200, job) : send(res, 404, errorBody('not_found', 'Job not found.'));
    }
    return send(res, 404, errorBody('not_found', 'Route not found.'));
  } catch (error) {
    console.error('request failed', error);
    if (!res.headersSent) send(res, 500, errorBody('internal_error', 'Internal server error.'));
    else res.destroy();
  }
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
